static const char* xl6IrInstructionKindName(XL6_IrInstructionKind kind);
static XL6_IrErrorAbi xl6IrNodeConstructionErrorAbi(const XL6_IrModule* module, XL6_IrNodeId id)
{
    const XL6_IrNode* node = xl6IrNodeGet(module, id);
    size_t capture;
    if (node != NULL && node->kind == XL6_IR_NODE_LOOP &&
        node->loopResourceAbi == XL6_IR_LOOP_RESOURCE_XVALUE_ITERATOR_DESTROY)
        return XL6_IR_ERROR_ABI_MAY_RAISE;
    /* A loop projection constructs its binding before that binding is live.
     * Keep this effect on the target so its failure has an exact prefix. */
    if (node != NULL && node->kind == XL6_IR_NODE_NAME) {
        const XL6_IrNode* targets = xl6IrNodeGet(module, node->parent);
        const XL6_IrNode* loop = targets != NULL ? xl6IrNodeGet(module, targets->parent) : NULL;
        if (loop != NULL && loop->kind == XL6_IR_NODE_LOOP && loop->sourceKind == XL6_AST_FOR &&
            loop->childCount == 3 && module->children[loop->firstChild] == node->parent &&
            targets->childCount != 0) {
            int key = loop->loopKeyAbi != XL6_IR_LOOP_KEY_NONE && module->children[targets->firstChild] == id;
            if ((key && (loop->loopKeyAbi == XL6_IR_LOOP_KEY_STRING_COPY ||
                         loop->loopKeyAbi == XL6_IR_LOOP_KEY_DYNAMIC_XVALUE)) ||
                (!key && (loop->loopItemAbi == XL6_IR_LOOP_ITEM_STRING_COPY ||
                          loop->loopItemAbi == XL6_IR_LOOP_ITEM_DYNAMIC_LOGICAL_XVALUE ||
                          loop->loopItemAbi == XL6_IR_LOOP_ITEM_NULLABLE_STRING_COPY ||
                          loop->loopItemAbi == XL6_IR_LOOP_ITEM_NULLABLE_CLOSURE_COPY ||
                          loop->loopItemAbi == XL6_IR_LOOP_ITEM_CLOSURE_COPY)))
                return XL6_IR_ERROR_ABI_MAY_RAISE;
        }
    }
    /* Mutable capture analysis fixes which declaration acquires a shared
     * cell. Its allocation effect is independent of the initial value. */
    for (capture = 0; node != NULL && capture < module->closureCaptureCount; ++capture) {
        const XL6_IrClosureCapture* item = &module->closureCaptures[capture];
        if (item->abi == XL6_IR_CLOSURE_CAPTURE_RETAIN_CELL && item->sourceSymbol != 0 &&
            item->sourceSymbol < module->symbolNodeCapacity && module->symbolNodes[item->sourceSymbol] == id)
            return XL6_IR_ERROR_ABI_MAY_RAISE;
    }
    if (node != NULL &&
        (node->namedCallableAbi == XL6_IR_NAMED_CALLABLE_CAPTURE_FREE_ADAPTER ||
         (node->kind == XL6_IR_NODE_FUNC_DECL && node->sourceKind == XL6_AST_ANON_FUNC)))
        return XL6_IR_ERROR_ABI_MAY_RAISE;
    /* Even a zero-payload variant allocates its object and tag. This effect
     * belongs to construction itself, independently of payload evaluation. */
    if (node != NULL && node->kind == XL6_IR_NODE_CALL &&
        node->callKind == XL6_SEM_CALL_ENUM_VARIANT) {
        const XL6_IrType* type = xl6IrTypeGet(&module->types, node->storageType);
        if (type != NULL && type->kind == XL6_IR_TYPE_TAGGED_ENUM)
            return XL6_IR_ERROR_ABI_MAY_RAISE;
    }
    /* Every literal allocates a carrier, including empty containers. Map
     * replacement may additionally destroy a previously inserted element. */
    return node != NULL && node->kind == XL6_IR_NODE_COLLECTION &&
        (node->sourceKind == XL6_AST_ARRAY_LITERAL || node->sourceKind == XL6_AST_SET_LITERAL ||
         node->sourceKind == XL6_AST_LIST_LITERAL || node->sourceKind == XL6_AST_DICT_LITERAL)
        ? XL6_IR_ERROR_ABI_MAY_RAISE : XL6_IR_ERROR_ABI_INVALID;
}

int xl6IrRefreshConstructionAbis(XL6_IrModule* module)
{
    size_t i;
    if (module == NULL) return 0;
    for (i = 0; i < module->nodeCount; ++i)
        module->nodes[i].constructionErrorAbi = xl6IrNodeConstructionErrorAbi(module, (XL6_IrNodeId)(i + 1));
    return 1;
}

