static int xl6IrDiag(XL6_DiagList* diags, const XL6_IrNode* node, const char* message)
{
    if ( diags != NULL ) {
        /* Structural verifier failures may have no single source node, but a
         * zero location is suppressed by the CLI and turns a broken XLIR
         * contract into an opaque "compile failed".  Keep the diagnostic
         * visible while retaining node precision whenever it is available. */
        xl6DiagAdd(diags, node != NULL ? node->span.line : 1,
                   node != NULL ? node->span.column : 1, message);
    }
    return 0;
}

static int xl6IrGrow(void** items, size_t* capacity, size_t count, size_t itemSize)
{
    size_t next;
    void* grown;

    if ( count < *capacity ) {
        return 1;
    }
    next = *capacity == 0 ? 64 : *capacity * 2;
    if ( next < count + 1 || next > SIZE_MAX / itemSize ) {
        return 0;
    }
    grown = xrtRealloc(*items, next * itemSize);
    if ( grown == NULL ) {
        return 0;
    }
    *items = grown;
    *capacity = next;
    return 1;
}

static XL6_IrIntegerTarget xl6IrIntegerTargetFromFrontend(
    XL6_TypeAbiId abiId, const char* canonicalName)
{
    if ( abiId == xl6TypeAbiIdText("xrt.int8") ||
         (canonicalName != NULL && strcmp(canonicalName, "int8") == 0) )
        return XL6_IR_INTEGER_TARGET_SIGNED_8;
    if ( abiId == xl6TypeAbiIdText("xrt.uint8") ||
         (canonicalName != NULL && strcmp(canonicalName, "uint8") == 0) )
        return XL6_IR_INTEGER_TARGET_UNSIGNED_8;
    if ( abiId == xl6TypeAbiIdText("xrt.int16") ||
         (canonicalName != NULL && strcmp(canonicalName, "int16") == 0) )
        return XL6_IR_INTEGER_TARGET_SIGNED_16;
    if ( abiId == xl6TypeAbiIdText("xrt.uint16") ||
         (canonicalName != NULL && strcmp(canonicalName, "uint16") == 0) )
        return XL6_IR_INTEGER_TARGET_UNSIGNED_16;
    if ( abiId == xl6TypeAbiIdText("xrt.int32") ||
         (canonicalName != NULL && strcmp(canonicalName, "int32") == 0) )
        return XL6_IR_INTEGER_TARGET_SIGNED_32;
    if ( abiId == xl6TypeAbiIdText("xrt.uint32") ||
         (canonicalName != NULL && strcmp(canonicalName, "uint32") == 0) )
        return XL6_IR_INTEGER_TARGET_UNSIGNED_32;
    if ( abiId == xl6TypeAbiIdText("xrt.int64") ||
         (canonicalName != NULL &&
          (strcmp(canonicalName, "int") == 0 ||
           strcmp(canonicalName, "int64") == 0)) )
        return XL6_IR_INTEGER_TARGET_SIGNED_64;
    if ( abiId == xl6TypeAbiIdText("xrt.uint64") ||
         (canonicalName != NULL && strcmp(canonicalName, "uint64") == 0) )
        return XL6_IR_INTEGER_TARGET_UNSIGNED_64;
    if ( abiId == xl6TypeAbiIdText("xrt.char") ||
         (canonicalName != NULL && strcmp(canonicalName, "char") == 0) )
        return XL6_IR_INTEGER_TARGET_UNICODE_SCALAR;
    return XL6_IR_INTEGER_TARGET_INVALID;
}

static XL6_IrRuntimeResourceAbi xl6IrRuntimeResourceAbiFromName(
    const char* canonicalName)
{
    if ( canonicalName == NULL ) return XL6_IR_RUNTIME_RESOURCE_NONE;
    /* Admit resources only as their operations become closed XLIR contracts.
     * Keeping the full enum append-only lets channel/sync/collections adopt
     * the same representation without changing the established thread ABI. */
    if ( strcmp(canonicalName, "thread") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_THREAD;
    if ( strcmp(canonicalName, "channel") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_CHANNEL;
    if ( strcmp(canonicalName, "mutex") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_MUTEX;
    if ( strcmp(canonicalName, "cond") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_COND;
    if ( strcmp(canonicalName, "rwlock") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_RWLOCK;
    if ( strcmp(canonicalName, "sem") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_SEM;
    if ( strcmp(canonicalName, "Stack") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_STACK;
    if ( strcmp(canonicalName, "AvlTree") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_AVL_TREE;
    if ( strcmp(canonicalName, "SpscQueue") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_SPSC_QUEUE;
    if ( strcmp(canonicalName, "MpscQueue") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_MPSC_QUEUE;
    if ( strcmp(canonicalName, "MpmcQueue") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_MPMC_QUEUE;
    if ( strcmp(canonicalName, "WaitQueue") == 0 )
        return XL6_IR_RUNTIME_RESOURCE_WAIT_QUEUE;
    return XL6_IR_RUNTIME_RESOURCE_NONE;
}

static XL6_IrCAbi xl6IrCAbiFromFrontend(XL6_TypeAbiId abiId, const char* canonicalName)
{
    if ( canonicalName != NULL && strcmp(canonicalName, "void") == 0 ) return XL6_IR_C_ABI_VOID;
    if ( abiId == xl6TypeAbiIdText("xrt.bool") ) return XL6_IR_C_ABI_BOOL;
    if ( abiId == xl6TypeAbiIdText("xrt.char") ||
         (canonicalName != NULL && strcmp(canonicalName, "char") == 0) )
        return XL6_IR_C_ABI_CHAR_U32;
    if ( abiId == xl6TypeAbiIdText("xrt.int64") ) return XL6_IR_C_ABI_I64;
    if ( abiId == xl6TypeAbiIdText("xrt.uint64") ) return XL6_IR_C_ABI_U64;
    if ( abiId == xl6TypeAbiIdText("xrt.type") ||
         (canonicalName != NULL && strcmp(canonicalName, "type") == 0) )
        return XL6_IR_C_ABI_TYPE_ID;
    /* Bounded language integers use XLIR's sign-extended i64 execution ABI.
     * Their TypeId integerTarget and explicit wrapping conversion operations
     * carry normalization semantics; this is not a Cgen narrowing convention.
     * uint64 uses the separate lossless U64 execution ABI. */
    if ( abiId == xl6TypeAbiIdText("xrt.int8") || abiId == xl6TypeAbiIdText("xrt.uint8") ||
         abiId == xl6TypeAbiIdText("xrt.int16") || abiId == xl6TypeAbiIdText("xrt.uint16") ||
         abiId == xl6TypeAbiIdText("xrt.int32") || abiId == xl6TypeAbiIdText("xrt.uint32") )
        return XL6_IR_C_ABI_I64;
    if ( abiId == xl6TypeAbiIdText("xrt.float64") ) return XL6_IR_C_ABI_F64;
    if ( abiId == xl6TypeAbiIdText("xrt.float32") ||
         (canonicalName != NULL && strcmp(canonicalName, "float32") == 0) )
        return XL6_IR_C_ABI_F32;
    if ( abiId == xl6TypeAbiIdText("xrt.time") ||
         (canonicalName != NULL && strcmp(canonicalName, "time") == 0) )
        return XL6_IR_C_ABI_TIME_I64;
    if ( canonicalName != NULL ) {
        if ( strcmp(canonicalName, "c_char") == 0 ) return XL6_IR_C_ABI_C_CHAR;
        if ( strcmp(canonicalName, "c_schar") == 0 ) return XL6_IR_C_ABI_C_SCHAR;
        if ( strcmp(canonicalName, "c_uchar") == 0 ) return XL6_IR_C_ABI_C_UCHAR;
        if ( strcmp(canonicalName, "c_short") == 0 ) return XL6_IR_C_ABI_C_SHORT;
        if ( strcmp(canonicalName, "c_ushort") == 0 ) return XL6_IR_C_ABI_C_USHORT;
        if ( strcmp(canonicalName, "c_int") == 0 ) return XL6_IR_C_ABI_C_INT;
        if ( strcmp(canonicalName, "c_uint") == 0 ) return XL6_IR_C_ABI_C_UINT;
        if ( strcmp(canonicalName, "c_long") == 0 ) return XL6_IR_C_ABI_C_LONG;
        if ( strcmp(canonicalName, "c_ulong") == 0 ) return XL6_IR_C_ABI_C_ULONG;
        if ( strcmp(canonicalName, "c_longlong") == 0 ) return XL6_IR_C_ABI_C_LONGLONG;
        if ( strcmp(canonicalName, "c_ulonglong") == 0 ) return XL6_IR_C_ABI_C_ULONGLONG;
        if ( strcmp(canonicalName, "c_size") == 0 ) return XL6_IR_C_ABI_C_SIZE;
        if ( strcmp(canonicalName, "c_ssize") == 0 ) return XL6_IR_C_ABI_C_SSIZE;
        if ( strcmp(canonicalName, "c_ptrdiff") == 0 ) return XL6_IR_C_ABI_C_PTRDIFF;
        if ( strcmp(canonicalName, "c_intptr") == 0 ) return XL6_IR_C_ABI_C_INTPTR;
        if ( strcmp(canonicalName, "c_uintptr") == 0 ) return XL6_IR_C_ABI_C_UINTPTR;
        if ( strcmp(canonicalName, "c_bool") == 0 ) return XL6_IR_C_ABI_C_BOOL;
        if ( strcmp(canonicalName, "c_float") == 0 ) return XL6_IR_C_ABI_C_FLOAT;
        if ( strcmp(canonicalName, "c_double") == 0 ) return XL6_IR_C_ABI_C_DOUBLE;
        if ( strcmp(canonicalName, "c_wchar") == 0 ) return XL6_IR_C_ABI_C_WCHAR;
    }
    if ( canonicalName != NULL && strcmp(canonicalName, "string") == 0 ) return XL6_IR_C_ABI_MANAGED_STRING;
    if ( abiId == xl6TypeAbiIdText("xrt.bytes") ||
         (canonicalName != NULL && strcmp(canonicalName, "bytes") == 0) )
        return XL6_IR_C_ABI_MANAGED_BYTES;
    if ( canonicalName != NULL && strcmp(canonicalName, "point") == 0 ) return XL6_IR_C_ABI_RAW_POINTER;
    if ( xl6IrRuntimeResourceAbiFromName(canonicalName) !=
             XL6_IR_RUNTIME_RESOURCE_NONE )
        return XL6_IR_C_ABI_RUNTIME_XVALUE_PTR;
    /* A container whose elements are `var` is the runtime's boxed dynamic
     * collection ABI.  This is distinct from a statically typed generic
     * container: only these explicitly dynamic instances may use xvalue*. */
    if ( canonicalName != NULL &&
         (strcmp(canonicalName, "var") == 0 || strcmp(canonicalName, "array") == 0 ||
          strcmp(canonicalName, "list") == 0 || strcmp(canonicalName, "set") == 0 ||
          strcmp(canonicalName, "dict") == 0 || strcmp(canonicalName, "array<var>") == 0 ||
          strcmp(canonicalName, "list<var>") == 0 || strcmp(canonicalName, "set<var>") == 0 ||
          strcmp(canonicalName, "dict<var>") == 0) )
        return XL6_IR_C_ABI_RUNTIME_XVALUE_PTR;
    if ( canonicalName != NULL && strcmp(canonicalName, "error") == 0 ) return XL6_IR_C_ABI_RUNTIME_ERROR_PTR;
    if ( canonicalName != NULL && strcmp(canonicalName, "future") == 0 ) return XL6_IR_C_ABI_RUNTIME_FUTURE_PTR;
    if ( canonicalName != NULL && strcmp(canonicalName, "generator") == 0 ) return XL6_IR_C_ABI_RUNTIME_GENERATOR_PTR;
    if ( canonicalName != NULL && strcmp(canonicalName, "function") == 0 ) return XL6_IR_C_ABI_CLOSURE_PTR;
    return XL6_IR_C_ABI_UNSUPPORTED;
}

static XL6_IrOwnershipAbi xl6IrOwnershipAbiFromFrontend(
    XL6_TypeAbiId abiId, const char* canonicalName)
{
    XL6_IrCAbi cAbi = xl6IrCAbiFromFrontend(abiId, canonicalName);
    return (cAbi == XL6_IR_C_ABI_MANAGED_STRING || cAbi == XL6_IR_C_ABI_MANAGED_BYTES ||
            cAbi == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
            cAbi == XL6_IR_C_ABI_RUNTIME_ERROR_PTR || cAbi == XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
            cAbi == XL6_IR_C_ABI_RUNTIME_GENERATOR_PTR ||
            cAbi == XL6_IR_C_ABI_CLOSURE_PTR || cAbi == XL6_IR_C_ABI_RUNTIME_CELL_PTR)
        ? XL6_IR_OWNERSHIP_ABI_MANAGED :
        (cAbi != XL6_IR_C_ABI_UNSUPPORTED ? XL6_IR_OWNERSHIP_ABI_TRIVIAL :
         XL6_IR_OWNERSHIP_ABI_MANAGED);
}

/* Collection identity is fixed at the frontend-to-XLIR boundary.  The
 * canonical name is still available here, but no later stage is allowed to
 * recover container semantics from that diagnostic spelling. */
static XL6_IrCollectionAbi xl6IrCollectionAbiFromName(const char* canonicalName)
{
    if ( canonicalName == NULL ) return XL6_IR_COLLECTION_NONE;
    if ( strcmp(canonicalName, "array") == 0 || strcmp(canonicalName, "array<var>") == 0 )
        return XL6_IR_COLLECTION_ARRAY;
    if ( strcmp(canonicalName, "list") == 0 || strcmp(canonicalName, "list<var>") == 0 )
        return XL6_IR_COLLECTION_LIST;
    if ( strcmp(canonicalName, "set") == 0 || strcmp(canonicalName, "set<var>") == 0 )
        return XL6_IR_COLLECTION_SET;
    if ( strcmp(canonicalName, "dict") == 0 || strcmp(canonicalName, "dict<var>") == 0 )
        return XL6_IR_COLLECTION_DICT;
    return XL6_IR_COLLECTION_NONE;
}

static XL6_IrCollectionAbi xl6IrCollectionAbiFromType(
    XL6_IrTypeKind kind, const char* canonicalName)
{
    /* Bare array/list/set/dict are statically shaped collections whose item
     * ABI is erased to `var`; they are not open dynamic values.  Preserve the
     * shape on the TypeId even when the frontend has no generic parameter so
     * loops, indexing and members never have to recover it from syntax. */
    return (kind == XL6_IR_TYPE_BUILTIN ||
            kind == XL6_IR_TYPE_GENERIC_INSTANCE)
        ? xl6IrCollectionAbiFromName(canonicalName)
        : XL6_IR_COLLECTION_NONE;
}

static XL6_IrNullAbi xl6IrNullAbiFromCAbi(XL6_IrCAbi cAbi)
{
    switch ( cAbi ) {
    case XL6_IR_C_ABI_RUNTIME_XVALUE_PTR:
    case XL6_IR_C_ABI_MANAGED_BYTES:
        return XL6_IR_NULL_ABI_XVALUE_SENTINEL;
    case XL6_IR_C_ABI_MANAGED_STRING:
    case XL6_IR_C_ABI_NATIVE_HANDLE:
    case XL6_IR_C_ABI_RAW_POINTER:
    case XL6_IR_C_ABI_RUNTIME_ERROR_PTR:
    case XL6_IR_C_ABI_RUNTIME_FUTURE_PTR:
    case XL6_IR_C_ABI_RUNTIME_GENERATOR_PTR:
    case XL6_IR_C_ABI_CLOSURE_PTR:
    case XL6_IR_C_ABI_RUNTIME_VALUE_ITERATOR_PTR:
    case XL6_IR_C_ABI_STORAGE_REF_PTR:
        return XL6_IR_NULL_ABI_POINTER_SENTINEL;
    default:
        return XL6_IR_NULL_ABI_NONE;
    }
}

/* Nullable identity must use the same representation decision before and
 * after interning.  The frontend nullable ABI is only a family marker; the
 * physical C ABI is determined by the already-canonical payload.  Using the
 * marker as an interning key and then rewriting it during finalization creates
 * duplicate TypeIds for an otherwise identical nullable type. */
static XL6_IrCAbi xl6IrNullableCAbiForElement(const XL6_IrType* element)
{
    if ( element == NULL ) return XL6_IR_C_ABI_UNSUPPORTED;
    /* A pure-native class is a nominal value, not the raw handle itself.  A
     * NULL handle is therefore a valid present payload and cannot double as
     * nullable's absence sentinel.  Keep the boxed xvalue so presence and the
     * exact nominal TypeId survive independently. */
    if ( element->kind == XL6_IR_TYPE_CLASS &&
         element->cAbi == XL6_IR_C_ABI_NATIVE_HANDLE )
        return XL6_IR_C_ABI_RUNTIME_XVALUE_PTR;
    if ( element->nullAbi == XL6_IR_NULL_ABI_POINTER_SENTINEL ||
         element->nullAbi == XL6_IR_NULL_ABI_XVALUE_SENTINEL )
        return element->cAbi;
    return element->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
           element->cAbi != XL6_IR_C_ABI_UNSUPPORTED &&
           element->cAbi != XL6_IR_C_ABI_VOID &&
           element->cAbi != XL6_IR_C_ABI_PRODUCT
        ? XL6_IR_C_ABI_TAGGED_NULLABLE
        : XL6_IR_C_ABI_UNSUPPORTED;
}

/* MAY_RAISE carriers are part of the canonical type representation.  Fixed
 * runtime/scalar ABIs retain their stable historical names; compiler-owned
 * tagged values and structural products receive a TypeId-derived name.
 * Keeping this mapping here prevents Cgen from making a second, potentially
 * divergent type decision. */
static const char* xl6IrTypeExpectedErrorResultCName(
    const XL6_IrTypePool* pool, const XL6_IrType* type,
    char* structuralName, size_t structuralNameSize)
{
    size_t typeIndex;
    if ( pool == NULL || type == NULL ) return NULL;
    switch ( type->cAbi ) {
    case XL6_IR_C_ABI_BOOL: return "xlir_result_bool";
    case XL6_IR_C_ABI_I64: return "xlir_result_i64";
    case XL6_IR_C_ABI_TIME_I64: return "xlir_result_i64";
    case XL6_IR_C_ABI_U64: return "xlir_result_u64";
    case XL6_IR_C_ABI_TYPE_ID: return "xlir_result_type_id";
    case XL6_IR_C_ABI_F64: return "xlir_result_f64";
    case XL6_IR_C_ABI_F32: return "xlir_result_f32";
    case XL6_IR_C_ABI_CHAR_U32: return "xlir_result_char";
    case XL6_IR_C_ABI_MANAGED_STRING: return "xlir_result_string";
    case XL6_IR_C_ABI_MANAGED_BYTES: return "xlir_result_xvalue";
    case XL6_IR_C_ABI_RUNTIME_XVALUE_PTR: return "xlir_result_xvalue";
    case XL6_IR_C_ABI_RUNTIME_FUTURE_PTR: return "xlir_result_future";
    case XL6_IR_C_ABI_RUNTIME_GENERATOR_PTR: return "xlir_result_generator";
    case XL6_IR_C_ABI_C_CHAR: return "xlir_result_c_char";
    case XL6_IR_C_ABI_C_SCHAR: return "xlir_result_c_schar";
    case XL6_IR_C_ABI_C_UCHAR: return "xlir_result_c_uchar";
    case XL6_IR_C_ABI_C_SHORT: return "xlir_result_c_short";
    case XL6_IR_C_ABI_C_USHORT: return "xlir_result_c_ushort";
    case XL6_IR_C_ABI_C_INT: return "xlir_result_c_int";
    case XL6_IR_C_ABI_C_UINT: return "xlir_result_c_uint";
    case XL6_IR_C_ABI_C_LONG: return "xlir_result_c_long";
    case XL6_IR_C_ABI_C_ULONG: return "xlir_result_c_ulong";
    case XL6_IR_C_ABI_C_LONGLONG: return "xlir_result_c_llong";
    case XL6_IR_C_ABI_C_ULONGLONG: return "xlir_result_c_ullong";
    case XL6_IR_C_ABI_C_SIZE: return "xlir_result_c_size";
    case XL6_IR_C_ABI_C_SSIZE: return "xlir_result_c_ssize";
    case XL6_IR_C_ABI_C_PTRDIFF: return "xlir_result_c_ptrdiff";
    case XL6_IR_C_ABI_C_INTPTR: return "xlir_result_c_intptr";
    case XL6_IR_C_ABI_C_UINTPTR: return "xlir_result_c_uintptr";
    case XL6_IR_C_ABI_C_BOOL: return "xlir_result_c_bool";
    case XL6_IR_C_ABI_C_FLOAT: return "xlir_result_c_float";
    case XL6_IR_C_ABI_C_DOUBLE: return "xlir_result_c_double";
    case XL6_IR_C_ABI_C_WCHAR: return "xlir_result_c_wchar";
    case XL6_IR_C_ABI_RAW_POINTER:
    case XL6_IR_C_ABI_NATIVE_HANDLE: return "xlir_result_pointer";
    case XL6_IR_C_ABI_RUNTIME_ERROR_PTR: return "xlir_result_error";
    case XL6_IR_C_ABI_CLOSURE_PTR: return "xlir_result_closure";
    case XL6_IR_C_ABI_TAGGED_NULLABLE:
    case XL6_IR_C_ABI_PRODUCT:
    case XL6_IR_C_ABI_UNION:
        if ( structuralName == NULL || structuralNameSize == 0 ||
             type < pool->items || type >= pool->items + pool->count + 1 ) return NULL;
        typeIndex = (size_t)(type - pool->items) + 1;
        if ( snprintf(structuralName, structuralNameSize, "xlir_result_t%lu",
                      (unsigned long)typeIndex) < 0 ) return NULL;
        return structuralName;
    default:
        return "";
    }
}

static int xl6IrTypeDisplayUsesParameters(const XL6_IrType* type)
{
    return type != NULL && type->paramCount != 0 &&
           type->kind != XL6_IR_TYPE_FUNCTION &&
           type->kind != XL6_IR_TYPE_TUPLE;
}

static int xl6IrTypeDisplayNameLength(
    const XL6_IrTypePool* pool, const XL6_IrType* type,
    size_t depth, size_t* length)
{
    size_t result;
    size_t i;
    if ( pool == NULL || type == NULL || length == NULL || depth > 64 ||
         type->name == NULL || type->name[0] == '\0' ) return 0;
    result = strlen(type->name);
    if ( !xl6IrTypeDisplayUsesParameters(type) ) {
        *length = result;
        return 1;
    }
    if ( type->params == NULL || result > SIZE_MAX - 2 ) return 0;
    result += 2;
    for ( i = 0; i < type->paramCount; ++i ) {
        const XL6_IrType* parameter = xl6IrTypeGet(pool, type->params[i]);
        size_t parameterLength;
        if ( !xl6IrTypeDisplayNameLength(
                 pool, parameter, depth + 1, &parameterLength) ) return 0;
        if ( i != 0 ) {
            if ( result == SIZE_MAX ) return 0;
            result += 1;
        }
        if ( parameterLength > SIZE_MAX - result ) return 0;
        result += parameterLength;
    }
    *length = result;
    return 1;
}

static int xl6IrTypeWriteDisplayName(
    const XL6_IrTypePool* pool, const XL6_IrType* type,
    size_t depth, char** cursor)
{
    size_t nameLength;
    size_t i;
    if ( pool == NULL || type == NULL || cursor == NULL || *cursor == NULL ||
         depth > 64 || type->name == NULL || type->name[0] == '\0' ) return 0;
    nameLength = strlen(type->name);
    memcpy(*cursor, type->name, nameLength);
    *cursor += nameLength;
    if ( !xl6IrTypeDisplayUsesParameters(type) ) return 1;
    if ( type->params == NULL ) return 0;
    *(*cursor)++ = '<';
    for ( i = 0; i < type->paramCount; ++i ) {
        const XL6_IrType* parameter = xl6IrTypeGet(pool, type->params[i]);
        if ( i != 0 ) *(*cursor)++ = ',';
        if ( !xl6IrTypeWriteDisplayName(
                 pool, parameter, depth + 1, cursor) ) return 0;
    }
    *(*cursor)++ = '>';
    return 1;
}

static int xl6IrTypeFinalizeDisplayName(
    XL6_IrTypePool* pool, XL6_IrType* type)
{
    size_t length;
    char* displayName;
    char* cursor;
    if ( !xl6IrTypeDisplayNameLength(pool, type, 0, &length) ||
         length == SIZE_MAX ) return 0;
    displayName = (char*)xrtMalloc(length + 1);
    if ( displayName == NULL ) return 0;
    cursor = displayName;
    if ( !xl6IrTypeWriteDisplayName(pool, type, 0, &cursor) ||
         (size_t)(cursor - displayName) != length ) {
        xrtFree(displayName);
        return 0;
    }
    *cursor = '\0';
    if ( type->displayName != NULL ) {
        int matches = strcmp(type->displayName, displayName) == 0;
        xrtFree(displayName);
        return matches;
    }
    type->displayName = displayName;
    return 1;
}

static int xl6IrTypeDisplayNameMatches(
    const XL6_IrTypePool* pool, const XL6_IrType* type)
{
    size_t length;
    char* expected;
    char* cursor;
    int matches;
    if ( type == NULL || type->displayName == NULL ||
         !xl6IrTypeDisplayNameLength(pool, type, 0, &length) ||
         length == SIZE_MAX ) return 0;
    expected = (char*)xrtMalloc(length + 1);
    if ( expected == NULL ) return 0;
    cursor = expected;
    if ( !xl6IrTypeWriteDisplayName(pool, type, 0, &cursor) ||
         (size_t)(cursor - expected) != length ) {
        xrtFree(expected);
        return 0;
    }
    *cursor = '\0';
    matches = strcmp(type->displayName, expected) == 0;
    xrtFree(expected);
    return matches;
}

XL6_ValueAdmissionV1 xl6IrValueAdmissionAbiForType(const XL6_IrTypePool* pool, const XL6_IrType* type)
{
    if (!pool || !type) return XL6_VALUE_ADMIT_NONE;
    if (type->kind == XL6_IR_TYPE_NULLABLE) {
        const XL6_IrType* element=type->paramCount==1 && type->params
            ? xl6IrTypeGet(pool,type->params[0]) : NULL;
        /* No recursive walk through malformed/unverified nullable graphs. */
        if (!element || element->kind!=XL6_IR_TYPE_BUILTIN) return XL6_VALUE_ADMIT_NONE;
        type=element;
    }
    if (type->kind!=XL6_IR_TYPE_BUILTIN || type->collectionAbi!=XL6_IR_COLLECTION_NONE ||
        type->paramCount || type->returnCount) return XL6_VALUE_ADMIT_NONE;
    if (type->cAbi==XL6_IR_C_ABI_I64 || type->cAbi==XL6_IR_C_ABI_U64) {
        switch (type->integerTarget) {
        case XL6_IR_INTEGER_TARGET_SIGNED_8: return XL6_VALUE_ADMIT_I8;
        case XL6_IR_INTEGER_TARGET_SIGNED_16: return XL6_VALUE_ADMIT_I16;
        case XL6_IR_INTEGER_TARGET_SIGNED_32: return XL6_VALUE_ADMIT_I32;
        case XL6_IR_INTEGER_TARGET_SIGNED_64: return XL6_VALUE_ADMIT_I64;
        case XL6_IR_INTEGER_TARGET_UNSIGNED_8: return XL6_VALUE_ADMIT_U8;
        case XL6_IR_INTEGER_TARGET_UNSIGNED_16: return XL6_VALUE_ADMIT_U16;
        case XL6_IR_INTEGER_TARGET_UNSIGNED_32: return XL6_VALUE_ADMIT_U32;
        case XL6_IR_INTEGER_TARGET_UNSIGNED_64: return XL6_VALUE_ADMIT_U64;
        default: return XL6_VALUE_ADMIT_NONE;
        }
    }
    switch (type->cAbi) {
    case XL6_IR_C_ABI_BOOL: return XL6_VALUE_ADMIT_BOOL;
    case XL6_IR_C_ABI_F32: return XL6_VALUE_ADMIT_F32;
    case XL6_IR_C_ABI_F64: return XL6_VALUE_ADMIT_F64;
    case XL6_IR_C_ABI_CHAR_U32: return XL6_VALUE_ADMIT_CHAR;
    case XL6_IR_C_ABI_MANAGED_STRING: return XL6_VALUE_ADMIT_STRING;
    case XL6_IR_C_ABI_MANAGED_BYTES: return XL6_VALUE_ADMIT_BYTES;
    case XL6_IR_C_ABI_TIME_I64: return XL6_VALUE_ADMIT_TIME;
    case XL6_IR_C_ABI_RUNTIME_XVALUE_PTR: return XL6_VALUE_ADMIT_ANY;
    default: return XL6_VALUE_ADMIT_NONE;
    }
}

XL6_IrErrorAbi xl6IrTypedCollectionErrorAbi(XL6_IrTypedCollectionOp operation)
{
    return operation == XL6_IR_TYPED_COLLECTION_RESIZE
        ? XL6_IR_ERROR_ABI_MAY_RAISE : XL6_IR_ERROR_ABI_NO_RAISE;
}

XL6_ValueDefaultAbiV1 xl6IrValueDefaultAbiForType(const XL6_IrTypePool* pool,const XL6_IrType* type)
{
    if (!pool || !type) return XL6_VALUE_DEFAULT_INVALID;
    if (type->kind==XL6_IR_TYPE_NULLABLE) {
        return type->paramCount==1 && type->params && xl6IrTypeGet(pool,type->params[0])
            ? XL6_VALUE_DEFAULT_NULL : XL6_VALUE_DEFAULT_INVALID;
    }
    XL6_ValueAdmissionV1 rule=xl6IrValueAdmissionAbiForType(pool,type);
    if (rule>=XL6_VALUE_ADMIT_I8 && rule<=XL6_VALUE_ADMIT_U32)
        return XL6_VALUE_DEFAULT_INT;
    switch (rule) {
    case XL6_VALUE_ADMIT_ANY: return XL6_VALUE_DEFAULT_NULL;
    case XL6_VALUE_ADMIT_BOOL: return XL6_VALUE_DEFAULT_BOOL;
    case XL6_VALUE_ADMIT_U64: return XL6_VALUE_DEFAULT_UINT;
    case XL6_VALUE_ADMIT_F32: case XL6_VALUE_ADMIT_F64: return XL6_VALUE_DEFAULT_FLOAT;
    case XL6_VALUE_ADMIT_CHAR: return XL6_VALUE_DEFAULT_CHAR;
    case XL6_VALUE_ADMIT_STRING: return XL6_VALUE_DEFAULT_STRING;
    case XL6_VALUE_ADMIT_BYTES: return XL6_VALUE_DEFAULT_BYTES;
    case XL6_VALUE_ADMIT_TIME: return XL6_VALUE_DEFAULT_TIME;
    default: return XL6_VALUE_DEFAULT_FORBIDDEN;
    }
}

XL6_IrNativeSlotAbi xl6IrNativeSlotAbiForType(const XL6_IrTypePool* pool, const XL6_IrType* type)
{
    if (!pool || !type) return XL6_IR_NATIVE_SLOT_NONE;
    if (type->cAbi == XL6_IR_C_ABI_TAGGED_NULLABLE) {
        const XL6_IrType* element=type->kind == XL6_IR_TYPE_NULLABLE && type->paramCount == 1 && type->params
            ? xl6IrTypeGet(pool,type->params[0]) : NULL;
        if (!element || element->nullAbi != XL6_IR_NULL_ABI_NONE) return XL6_IR_NATIVE_SLOT_NONE;
        switch (element->cAbi) {
        case XL6_IR_C_ABI_BOOL: return XL6_IR_NATIVE_SLOT_NULLABLE_BOOL;
        case XL6_IR_C_ABI_I64: return XL6_IR_NATIVE_SLOT_NULLABLE_I64;
        case XL6_IR_C_ABI_U64: return XL6_IR_NATIVE_SLOT_NULLABLE_U64;
        case XL6_IR_C_ABI_F32: return XL6_IR_NATIVE_SLOT_NULLABLE_F32;
        case XL6_IR_C_ABI_F64: return XL6_IR_NATIVE_SLOT_NULLABLE_F64;
        case XL6_IR_C_ABI_TIME_I64: return XL6_IR_NATIVE_SLOT_NULLABLE_TIME;
        case XL6_IR_C_ABI_CHAR_U32: return XL6_IR_NATIVE_SLOT_NULLABLE_CHAR;
        default: return XL6_IR_NATIVE_SLOT_NONE;
        }
    }
    if (type->cAbi == XL6_IR_C_ABI_MANAGED_STRING)
        return type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ?
            (type->kind == XL6_IR_TYPE_NULLABLE ? XL6_IR_NATIVE_SLOT_NULLABLE_STRING : XL6_IR_NATIVE_SLOT_STRING) : XL6_IR_NATIVE_SLOT_NONE;
    if (type->cAbi == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR || type->cAbi == XL6_IR_C_ABI_MANAGED_BYTES)
        return type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ? XL6_IR_NATIVE_SLOT_XVALUE_CARRIER : XL6_IR_NATIVE_SLOT_NONE;
    switch (type->cAbi) {
    case XL6_IR_C_ABI_BOOL: return XL6_IR_NATIVE_SLOT_BOOL;
    case XL6_IR_C_ABI_I64: return XL6_IR_NATIVE_SLOT_I64;
    case XL6_IR_C_ABI_U64: return XL6_IR_NATIVE_SLOT_U64;
    case XL6_IR_C_ABI_F32: return XL6_IR_NATIVE_SLOT_F32;
    case XL6_IR_C_ABI_F64: return XL6_IR_NATIVE_SLOT_F64;
    case XL6_IR_C_ABI_TIME_I64: return XL6_IR_NATIVE_SLOT_TIME;
    case XL6_IR_C_ABI_TYPE_ID: return XL6_IR_NATIVE_SLOT_TYPE_ID;
    case XL6_IR_C_ABI_CHAR_U32: return XL6_IR_NATIVE_SLOT_CHAR;
    case XL6_IR_C_ABI_C_CHAR: return XL6_IR_NATIVE_SLOT_C_CHAR;
    case XL6_IR_C_ABI_C_SCHAR: return XL6_IR_NATIVE_SLOT_C_SCHAR;
    case XL6_IR_C_ABI_C_UCHAR: return XL6_IR_NATIVE_SLOT_C_UCHAR;
    case XL6_IR_C_ABI_C_SHORT: return XL6_IR_NATIVE_SLOT_C_SHORT;
    case XL6_IR_C_ABI_C_USHORT: return XL6_IR_NATIVE_SLOT_C_USHORT;
    case XL6_IR_C_ABI_C_INT: return XL6_IR_NATIVE_SLOT_C_INT;
    case XL6_IR_C_ABI_C_UINT: return XL6_IR_NATIVE_SLOT_C_UINT;
    case XL6_IR_C_ABI_C_LONG: return XL6_IR_NATIVE_SLOT_C_LONG;
    case XL6_IR_C_ABI_C_ULONG: return XL6_IR_NATIVE_SLOT_C_ULONG;
    case XL6_IR_C_ABI_C_LONGLONG: return XL6_IR_NATIVE_SLOT_C_LONGLONG;
    case XL6_IR_C_ABI_C_ULONGLONG: return XL6_IR_NATIVE_SLOT_C_ULONGLONG;
    case XL6_IR_C_ABI_C_SIZE: return XL6_IR_NATIVE_SLOT_C_SIZE;
    case XL6_IR_C_ABI_C_SSIZE: return XL6_IR_NATIVE_SLOT_C_SSIZE;
    case XL6_IR_C_ABI_C_PTRDIFF: return XL6_IR_NATIVE_SLOT_C_PTRDIFF;
    case XL6_IR_C_ABI_C_INTPTR: return XL6_IR_NATIVE_SLOT_C_INTPTR;
    case XL6_IR_C_ABI_C_UINTPTR: return XL6_IR_NATIVE_SLOT_C_UINTPTR;
    case XL6_IR_C_ABI_C_BOOL: return XL6_IR_NATIVE_SLOT_C_BOOL;
    case XL6_IR_C_ABI_C_FLOAT: return XL6_IR_NATIVE_SLOT_C_FLOAT;
    case XL6_IR_C_ABI_C_DOUBLE: return XL6_IR_NATIVE_SLOT_C_DOUBLE;
    case XL6_IR_C_ABI_C_WCHAR: return XL6_IR_NATIVE_SLOT_C_WCHAR;
    default: return XL6_IR_NATIVE_SLOT_NONE;
    }
}
