                resultMatches = worker != NULL && worker->cAbi == XL6_IR_C_ABI_I64;
                break;
            case XL6_IR_ASYNC_RESULT_COPY_U64:
                resultMatches = worker != NULL && worker->cAbi == XL6_IR_C_ABI_U64;
                break;
            case XL6_IR_ASYNC_RESULT_COPY_TYPE_ID:
