                node->opcode == XL6_IR_OPCODE_BIT_AND ||
                node->opcode == XL6_IR_OPCODE_BIT_OR ||
                node->opcode == XL6_IR_OPCODE_BIT_XOR ||
                node->opcode == XL6_IR_OPCODE_LT ||
                node->opcode == XL6_IR_OPCODE_LE ||
                node->opcode == XL6_IR_OPCODE_GT ||
                node->opcode == XL6_IR_OPCODE_GE;
